const s = $getWorkflowStaticData('global');
const mk = (prefix, dept, n) => Array.from({ length: n }, (_, i) => ({
  id: prefix + '_' + String(i + 1).padStart(2, '0'), dept, level: 'Junior',
  tasks_done: 0, tasks_assigned: 10, spent_kwd: 0, monthly_allowance_kwd: 1
}));
if (!s.employees) {
  s.employees = [].concat(mk('inn', 'innovation_lab', 11), mk('hr', 'hr', 4), mk('mkt', 'marketing', 12), mk('coach', 'skills_coach', 3));
}
s.target_kwd = s.target_kwd || 200;
s.planning_meetings_per_month = s.planning_meetings_per_month || 2;
s.cells = s.cells || [];
s.history = s.history || [];
const body = ($input.first().json || {}).body || {};
for (const p of (body.performance || [])) {
  const e = s.employees.find(x => x.id === p.id);
  if (e) Object.assign(e, {
    tasks_done: Number(p.tasks_done ?? e.tasks_done),
    tasks_assigned: Number(p.tasks_assigned ?? e.tasks_assigned),
    spent_kwd: Number(p.spent_kwd ?? e.spent_kwd)
  });
}
if (body.monthly_revenue_kwd !== undefined) s.last_revenue_kwd = Number(body.monthly_revenue_kwd);
return [{ json: {
  target_kwd: s.target_kwd,
  revenue_kwd: s.last_revenue_kwd || 0,
  planning_meetings_per_month: s.planning_meetings_per_month,
  existing_games: s.cells.map(c => c.game),
  headcount: s.employees.length
} }];

const raw = String($input.first().json.output || '[]');
const m = raw.match(/\[[\s\S]*\]/);
let games = [];
try { games = JSON.parse(m ? m[0] : raw); } catch (e) { games = []; }
return [{ json: { games } }];

