const s = $getWorkflowStaticData('global');
const raw = String($input.first().json.output || '{}');
const m = raw.match(/\{[\s\S]*\}/);
let hr = {};
try { hr = JSON.parse(m ? m[0] : raw); } catch (e) { hr = { cells: [] }; }
const LEVELS = ['Junior', 'Senior', 'Lead'];
const promoted = [], doubled = [], overBudget = [];
for (const e of s.employees) {
  const rate = e.tasks_assigned ? e.tasks_done / e.tasks_assigned : 0;
  const withinBudget = (e.spent_kwd || 0) <= (e.monthly_allowance_kwd || 1);
  if (!withinBudget) overBudget.push(e.id);
  if (rate >= 0.9 && withinBudget && e.level !== 'Lead') {
    e.level = LEVELS[LEVELS.indexOf(e.level) + 1]; promoted.push({ id: e.id, level: e.level });
  } else if (rate < 0.6) {
    e.tasks_assigned = Math.min(e.tasks_assigned * 2, 80); doubled.push({ id: e.id, tasks: e.tasks_assigned });
  }
  e.tasks_done = 0; e.spent_kwd = 0;
}
const newCells = [];
for (const c of (hr.cells || [])) {
  const cellId = 'cell_' + String(s.cells.length + newCells.length + 11).padStart(2, '0');
  const members = (c.members || []).slice(0, 5).map((mbr, i) => ({ id: cellId + '_' + (i + 1), name: mbr.name, role: mbr.role, dept: 'production', level: 'Junior', tasks_done: 0, tasks_assigned: 10, spent_kwd: 0, monthly_allowance_kwd: 1 }));
  newCells.push({ cell_id: cellId, game: c.game, shift: (s.cells.length + newCells.length) % 2 === 0 ? 'A' : 'B', members: members.map(x => x.id) });
  s.employees.push(...members);
}
s.cells.push(...newCells);
return [{ json: {
  new_cells: newCells, promoted, doubled, over_budget: overBudget,
  monthly_budget_kwd: s.employees.length * 1,
  headcount: s.employees.length,
  hr_note: hr.hr_note || '',
  games: $('Parse New Games').first().json.games
} }];

