const s = $getWorkflowStaticData('global');
const raw = String($input.first().json.output || '{}');
const m = raw.match(/\{[\s\S]*\}/);
let mkt = {};
try { mkt = JSON.parse(m ? m[0] : raw); } catch (e) { mkt = {}; }
const revenue = s.last_revenue_kwd || 0;
const oldTarget = s.target_kwd;
const hit = revenue >= oldTarget;
if (hit) {
  s.target_kwd = Math.round(oldTarget * 1.25 * 100) / 100;
  s.planning_meetings_per_month += 1;
}
s.history.push({ at: new Date().toISOString(), revenue, target: oldTarget, hit });
return [{ json: {
  target_hit: hit, revenue_kwd: revenue, old_target_kwd: oldTarget, new_target_kwd: s.target_kwd,
  planning_meetings_per_month: s.planning_meetings_per_month,
  chant: hit ? 'يا قادسية يا ملكي 💛💙 | Visca el Barça | يا أزرق! حققنا التارقت!' : '',
  marketing: mkt
} }];

